begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();conn uuid;h text:=md5(gen_random_uuid()::text)||md5(gen_random_uuid()::text);a uuid;b uuid;other_app uuid;lease uuid;version integer;claim jsonb;p jsonb;result jsonb;again jsonb;
begin
 insert into auth.users(id) values(u),(v);
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Application jobs',h,array['workspace:read','preferences:write','drafts:write','approvals:read','resumes:read'],now()+interval '1 hour') returning id into conn;
 p:='{"posting":{"id":"selected-public-job","url":"https://job-boards.greenhouse.io/fixture/jobs/2001","company":"Fictional Systems","title":"Fictional Backend Engineer","employmentType":"FT","location":"Remote"},"expectedRevision":0,"eventKey":"human-click:1"}';
 perform set_config('test.uid',u::text,true);execute 'set local role authenticated';
 result:=public.queue_application_job(p);a:=(result->'application'->>'id')::uuid;b:=(result->'job'->>'id')::uuid;
 if result->'job'->>'status'<>'queued' or result->'application'->'execution_job'->>'status'<>'queued' then raise exception 'Queue has no durable projected receipt';end if;
 if public.queue_application_job(p)<>result then raise exception 'Human retry duplicated';end if;
 begin update public.applications set execution_job='{"status":"completed"}' where id=a;raise exception 'Human forged job state';exception when insufficient_privilege then null;end;
 begin perform public.queue_application_job(p||'{"ownerId":"other"}');raise exception 'Owner injection';exception when invalid_parameter_value then null;end;
 begin perform public.queue_application_job(p||'{"expectedRevision":1}');raise exception 'Changed retry';exception when serialization_failure then null;end;
 begin perform public.queue_application_job(jsonb_set(p,'{posting,url}','"http://127.0.0.1/private"'));raise exception 'Unsafe posting';exception when invalid_parameter_value then null;end;
 execute 'reset role';
 if public.agent_dispatch(h,'applications.submit_job',p)<>result then raise exception 'Website/MCP mismatch';end if;
 again:=public.backend_job_dispatch(h,'applications.submit_job',p||'{"eventKey":"mcp-click:2"}');
 if again->'job'->>'id'<>b::text or (select count(*) from private.backend_jobs where user_id=u)<>1 then raise exception 'Double click queued duplicate active job';end if;
 if (select receipt from public.applications where id=a) is not null or (select status from public.applications where id=a)<>'Queued' or exists(select 1 from public.approvals where application_id=a) then raise exception 'Queue minted submission/approval';end if;
 begin perform public.backend_job_dispatch(h,'backend.jobs.submit',jsonb_build_object('kind','application_submit','input',jsonb_build_object('applicationId',a,'expectedRevision',0),'eventKey','generic-queue'));raise exception 'Generic queue bypass';exception when invalid_parameter_value then null;end;
 -- Search-only workers leave application work alone; no feature flag can claim it accidentally.
 if public.backend_worker('claim','{}') is not null then raise exception 'Search worker claimed application';end if;
 if public.backend_worker('claim_application','{}') is not null then raise exception 'Deterministic worker claimed Muse work';end if;
 p:=jsonb_build_object('jobId',b,'expectedVersion',1,'expectedRevision',0,'eventKey','muse-claim:1');
 result:=public.backend_job_dispatch(h,'applications.request.claim',p);
 if result->'job'->>'status'<>'running' or result->'job'->'result'->>'executor'<>'muse' then raise exception 'Muse did not own request';end if;
 if public.backend_job_dispatch(h,'applications.request.claim',p)<>result then raise exception 'Pickup retry duplicated work';end if;
 begin perform public.backend_job_dispatch(h,'applications.request.claim',p||'{"eventKey":"competing-claim"}');raise exception 'Duplicate pickup';exception when serialization_failure then null;end;
 if public.backend_worker('claim_application','{}') is not null or public.backend_worker('claim','{}') is not null then raise exception 'Worker stole Muse request';end if;
 begin perform public.backend_worker('application_dispatch',jsonb_build_object('name','runner_submission_transition','args',jsonb_build_object('operation','claim')));raise exception 'Deterministic submission unpaused';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.submission_attempts where application_id=a) then raise exception 'Pickup created submission attempt';end if;
 -- A second same-owner connection can read but cannot take/report this assigned request.
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Other agent',repeat('f',64),array['workspace:read','preferences:write','drafts:write','approvals:read','resumes:read'],now()+interval '1 hour');
 begin perform public.backend_job_dispatch(repeat('f',64),'applications.request.report',p||'{"expectedVersion":2,"outcome":"completed","summary":"Forged claim","eventKey":"other-report"}');raise exception 'Other connection reported';exception when insufficient_privilege then null;end;
 p:=p||'{"expectedVersion":2,"eventKey":"muse-result:1","outcome":"prepared","summary":"Saved draft checked; waiting for human review."}';
 begin perform public.backend_job_dispatch(h,'applications.request.report',p||'{"expectedRevision":4}');raise exception 'Stale draft reported';exception when serialization_failure then null;end;
 result:=public.backend_job_dispatch(h,'applications.request.report',p);
 if result->'job'->>'status'<>'completed' or result->'job'->'result'->>'outcome'<>'prepared' or result->'job'->'result'->>'verifiedSubmission'<>'false' then raise exception 'Outcome missing or falsely verified';end if;
 if public.backend_job_dispatch(h,'applications.request.report',p)<>result then raise exception 'Outcome retry changed';end if;
 if (select status from public.applications where id=a)<>'Queued' or exists(select 1 from public.approvals where application_id=a) or exists(select 1 from public.submission_attempts where application_id=a) then raise exception 'Report minted approval/submission';end if;
 if (select execution_job->'result'->>'outcome' from public.applications where id=a)<>'prepared' then raise exception 'Visible projection missing';end if;
 if not exists(select 1 from public.activity_events where user_id=u and kind='muse.application_requested' and payload->>'recordId'=b::text) then raise exception 'Missing Muse request event';end if;
 if not exists(select 1 from jsonb_array_elements(public.agent_dispatch(h,'changes.read','{}')->'items') x where x->>'kind'='application_requested' and x->>'recordId'=b::text) then raise exception 'Request missing from feed';end if;
 update private.agent_connections set revoked_at=now() where id=conn;
 begin perform public.backend_job_dispatch(h,'applications.request.report',p);raise exception 'Revoked authority';exception when insufficient_privilege or invalid_authorization_specification then null;end;
 perform set_config('test.uid',v::text,true);execute 'set local role authenticated';
 if jsonb_array_length(public.backend_job_action('backend.jobs.read','{}')->'jobs')<>0 then raise exception 'Other owner sees application job';end if;
 begin perform public.queue_application_job((select payload from private.backend_requests where user_id=u and event_key='human-click:1'));raise exception 'Missing execution connection accepted';exception when insufficient_privilege then null;end;
 begin perform public.backend_worker('claim_application','{}');raise exception 'Human claimed worker';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $$;
rollback;
